Q: switch-case statement without break A: <ul>
<li><p>If you don't include break in any of case then all the case below will be executed and until it sees break.</p>
</li>
<li><p>And if you don't include break in default then it will cause no effect as there are not any case below this 'Default' case.</p>
</li>
<li><p>And not using break generally considered as a bad practice but some time it may also come handy because of its fall-through nature.</p>
<p>For example:</p>
</li>
</ul>
<pre><code>  case optionA:
       //optionA needs to do its own thing, and also B's thing.
       //Fall-through to optionB afterwards.
       //Its behaviour is a superset of B's.

  case optionB:
       // optionB needs to do its own thing
       // Its behaviour is a subset of A's.
       break;

  case optionC:
       // optionC is quite independent so it does its own thing.
       break;
</code></pre>

Q: STM32 wake up from standby mode every 10 seconds A: <p>Finally found a solution using IWDG. This code works for PlatformIO using the arduino framework</p>
<pre><code>#include &lt;Arduino.h&gt;
#include &lt;IWatchdog.h&gt; // &lt;----------- needed

void setup(void)
{
    // start serial
    Serial.begin(115200);

    // set pins
    pinMode(LED_BUILTIN, OUTPUT);
    pinMode(A0, INPUT_PULLUP); // connect button to this pin to simulate a sensor for purposes of this example.

    // flash led to indicate board is starting
    Serial.println(&quot;starting...&quot;);
    digitalWrite(LED_BUILTIN, HIGH);
    delay(250);
    digitalWrite(LED_BUILTIN, LOW);

    // read value from sensor. In this case just tell if button is presses
    // connect one side of button to pin A0 and the other to ground
    int sensorValue = digitalRead(A0);

    // if button is not pressed
    if (sensorValue == 1)
    {
        // go to sleep and try again in 4 seconds
        Serial.println(&quot;going to sleep and trying again in 4 seconds...&quot;);

        // Initialize the IWDG with 4 seconds timeout.
        // This would cause a CPU reset if the IWDG timer
        // is not reloaded in approximately 4 seconds.
        IWatchdog.begin(4000000);

        // go to sleep
        HAL_PWR_EnterSTANDBYMode();

        Serial.println(&quot;This line should NOT print!!!!!&quot;);
    }


    // at this point it means the button is was pressed
    Serial.println(&quot;staying awake!&quot;);
    // stay awake flashing led
    while (true)
    {
        digitalWrite(LED_BUILTIN, HIGH);
        delay(50);
        digitalWrite(LED_BUILTIN, LOW);
        delay(50);
    }
}

void loop()
{
}
</code></pre>
